import assert from "node:assert/strict";
import { test } from "node:test";
import { toResource } from "../src/api.ts";
import { branchOf, byBranch, isUntagged, matches, toEnvResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

function raw(id: string, extra: Record<string, unknown> = {}): Record<string, unknown> {
  return { id, type: "instance", name: id, cost_month_cents: 100, ...extra };
}

test("envctl adapts label keys without changing values or the shared normalizer", () => {
  const input = raw("cdk", { labels: { BrAnCh: "feat-ledger", TEAM: "Payments" } });
  const resource = toEnvResource(input);
  assert.equal(branchOf(resource), "feat-ledger");
  assert.ok(matches(resource, [["team", "Payments"]]));
  assert.ok(!matches(resource, [["team", "payments"]]));
  assert.equal(isUntagged(resource), false);
  assert.equal(byBranch([resource]).get("feat-ledger")?.length, 1);
  assert.doesNotMatch(summarize([resource]), /untagged resources/);
  assert.deepEqual(toResource(input).tags, {});
  assert.deepEqual(input.labels, { BrAnCh: "feat-ledger", TEAM: "Payments" });
});

test("legacy tags take precedence over labels, and missing metadata remains untagged", () => {
  assert.equal(branchOf(toEnvResource(raw("mixed", {
    tags: { branch: "feat-other" }, labels: { Branch: "feat-ledger" },
  }))), "feat-other");
  assert.ok(isUntagged(toEnvResource(raw("missing"))));
  assert.ok(isUntagged(toEnvResource(raw("null", { tags: null, labels: null }))));
});

test("plans include labeled resources and exact stack ownership, not similar branches", () => {
  const resources = [
    raw("net", { tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    raw("boot", { stack_id: "stk-feat-ledger" }),
    raw("cdk", { labels: { Branch: "feat-ledger" }, depends_on: ["net", "boot"] }),
    raw("other", { labels: { Branch: "feat-payroll" } }),
    raw("similar", { stack_id: "stk-feat-ledger-v2" }),
    raw("different-case", { labels: { Branch: "Feat-ledger" } }),
    raw("explicit-other", { tags: { branch: "feat-other" }, stack_id: "stk-feat-ledger" }),
    raw("unowned", { name: "feat-ledger-lookalike" }),
  ].map(toEnvResource);
  const plan = buildPlan(resources, "feat-ledger");
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s) => s.id), ["cdk", "net", "boot"]);
});

test("real external labeled dependents still block teardown", () => {
  const resources = [
    raw("net", { tags: { branch: "feat-ledger" } }),
    raw("external", { labels: { Branch: "feat-other" }, depends_on: ["net"] }),
  ].map(toEnvResource);
  assert.deepEqual(buildPlan(resources, "feat-ledger").blocked, [
    { id: "net", dependents: ["external"] },
  ]);
});
