  const api = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  async function run(...args: string[]) {
    const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args], {
      env: { ...process.env, ENVCTL_API: api, ENVCTL_TOKEN: "test-token" },
      stdio: ["ignore", "pipe", "pipe"], timeout: 10000,
    });
    let stdout = "", stderr = "";
    child.stdout.on("data", (data) => { stdout += data; });
    child.stderr.on("data", (data) => { stderr += data; });
    return new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve, reject) => {
      child.on("error", reject);
      child.on("close", (code) => resolve({ code, stdout, stderr }));
    });
  }
  return { run, deleted, remaining, requests };
}

function raw(id: string, extra: Record<string, unknown> = {}) {
  return { id, type: "instance", name: id, cost_month_cents: 100, ...extra };
}

test("CLI preserves labels across pages, retries 429, and tears down only the requested branch", async (t) => {
  const resources = [
    raw("net", { tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    raw("boot", { stack_id: "stk-feat-ledger" }),
    ...Array.from({ length: 20 }, (_, i) => raw(`other-${i}`, { tags: { branch: "feat-ledger-v2" } })),
    raw("vol", { labels: { BRANCH: "feat-ledger", Team: "payments" } }),
    raw("app", { labels: { Branch: "feat-ledger" }, depends_on: ["net", "boot", "vol"] }),
    raw("dns", { labels: { bRaNcH: "feat-ledger" }, depends_on: ["app"] }),
    raw("payroll", { labels: { Branch: "feat-payroll" } }),
    raw("orphan"),
  ];
  const api = await mockApi(t, resources, true);
  const planResult = await api.run("plan", "--branch", "feat-ledger", "--json");
  assert.equal(planResult.code, 0, planResult.stderr);
  assert.match(planResult.stderr, /rate limited/);
  const plan = JSON.parse(planResult.stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s: { id: string }) => s.id), ["dns", "app", "net", "boot", "vol"]);
  assert.ok(api.requests.some((r) => r.cursor === "page 2&more"));
  assert.ok(api.requests.every((r) => r.auth === "Bearer test-token"));

  const list = await api.run("list");
  assert.equal(list.code, 0, list.stderr);
  assert.match(list.stdout, /feat-ledger\s+4\s/);
  assert.match(list.stdout, /feat-payroll\s+1\s/);
  const gc = await api.run("gc", "--untagged");
  assert.equal(gc.code, 0, gc.stderr);
  assert.match(gc.stdout, /^2 untagged resources/);
  const dryRun = await api.run("teardown", "--branch", "feat-ledger", "--dry-run");
  assert.equal(dryRun.code, 0, dryRun.stderr);
  assert.deepEqual(api.deleted, []);

  const teardown = await api.run("teardown", "--branch", "feat-ledger");
  assert.equal(teardown.code, 0, teardown.stderr);
  assert.deepEqual(api.deleted, ["dns", "app", "net", "boot", "vol"]);
  assert.equal(api.remaining.size, resources.length - 5);
  assert.ok(api.remaining.has("payroll") && api.remaining.has("orphan") && api.remaining.has("other-0"));
});

test("CLI still refuses teardown when a different labeled branch depends on it", async (t) => {
  const api = await mockApi(t, [
    raw("net", { tags: { branch: "feat-ledger" } }),
    raw("external", { labels: { Branch: "feat-payroll" }, depends_on: ["net"] }),
  ]);
  const result = await api.run("teardown", "--branch", "feat-ledger");
  assert.equal(result.code, 1);
  assert.match(result.stderr, /refusing to tear down/);
  assert.match(result.stdout, /external.*outside this branch/);
  assert.deepEqual(api.deleted, []);
});

test("CLI reports listing API errors without attempting deletion", async (t) => {
  const api = await mockApi(t, [], false, true);
  const result = await api.run("teardown", "--branch", "feat-ledger");
  assert.equal(result.code, 1);
  assert.match(result.stderr, /403: forbidden/);
  assert.deepEqual(api.deleted, []);
});
